def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform line separating two panels.
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            left_w = c
            right_w = w - c - 1
            if left_w == right_w and left_w > 0:
                left = [row[:c] for row in grid]
                right = [row[c + 1:] for row in grid]
                common = set(x for row in left for x in row) & set(
                    x for row in right for x in row
                )
                if len(common) == 1:
                    color = next(iter(common))
                    # When the panels share a single color, that color is
                    # the uniform output.
                    return [[color] * left_w for _ in range(h)]

                # Otherwise encode the left panel's two colors.
                colors = sorted(set(x for row in left for x in row))
                if len(colors) == 2:
                    return [[2 if x == colors[0] else 3 for x in row] for row in left]
                return [row[:] for row in left]

    for r in range(h):
        if len(set(grid[r])) == 1:
            top_h = r
            if top_h > 0 and h - r - 1 == top_h:
                top = grid[:r]
                colors = sorted(set(x for row in top for x in row))
                if len(colors) == 2:
                    return [[4 if x == colors[0] else 3 for x in row] for row in top]
                return [row[:] for row in top]

    return [row[:] for row in grid]
