def transform(grid):
    h, w = len(grid), len(grid[0])

    # Compare equal-sized panels separated by a uniform vertical line.
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            left_width = c
            right_width = w - c - 1
            if left_width == right_width and left_width > 0:
                left = [row[:c] for row in grid]
                right = [row[c + 1:] for row in grid]
                common = set(x for row in left for x in row) & set(
                    x for row in right for x in row
                )
                base = next(iter(common)) if len(common) == 1 else 0
                return [
                    [3 if left[r][k] == right[r][k] else base
                     for k in range(left_width)]
                    for r in range(h)
                ]

    # Compare equal-sized panels above and below a uniform horizontal line.
    for r in range(h):
        if len(set(grid[r])) == 1:
            top_height = r
            bottom_height = h - r - 1
            if top_height == bottom_height and top_height > 0:
                top = grid[:r]
                bottom = grid[r + 1:]
                common = set(x for row in top for x in row) & set(
                    x for row in bottom for x in row
                )
                base = next(iter(common)) if len(common) == 1 else 0
                return [
                    [3 if top[i][j] == bottom[i][j] else base
                     for j in range(len(grid[0]))]
                    for i in range(top_height)
                ]

    return [row[:] for row in grid]
